class_name Hazard
extends Area2D

@export var damage: int = 1


func _ready() -> void:
	body_entered.connect(_on_body_entered)


func _on_body_entered(body: Node2D) -> void:
	if body.has_method("take_damage"):
		body.take_damage(damage)

class_name Checkpoint
extends Area2D

signal activated(new_position: Vector2)

var is_active: bool = false


func _ready() -> void:
	body_entered.connect(_on_body_entered)


func _on_body_entered(body: Node2D) -> void:
	if is_active:
		return

	if body.is_in_group("player"):
		is_active = true
		activated.emit(global_position)

extends CharacterBody2D

@export var speed: float = 200.0
@export var jump_velocity: float = -400.0
@export var state_machine: StateMachine

var gravity: float = 980.0
var is_on_ladder: bool = false
var spawn_position: Vector2
var is_dead: bool = false

@onready var animated_sprite: AnimatedSprite2D = $AnimatedSprite2D
@onready var animation_player: AnimationPlayer = $AnimationPlayer
@onready var animation_tree: AnimationTree = $AnimationTree

var playback: AnimationNodeStateMachinePlayback


func _ready() -> void:
	add_to_group("player")
	spawn_position = global_position
	if animation_tree:
		playback = animation_tree["parameters/playback"]


func set_spawn_position(new_position: Vector2) -> void:
	spawn_position = new_position


func take_damage(_amount: int) -> void:
	if is_dead:
		return

	is_dead = true
	velocity = Vector2.ZERO
	set_physics_process(false)

	await get_tree().create_timer(1.0).timeout

	respawn()


func respawn() -> void:
	global_position = spawn_position
	velocity = Vector2.ZERO
	is_dead = false
	set_physics_process(true)
	if state_machine:
		state_machine._on_child_transitioned(state_machine.current_state, "idle")


func _physics_process(delta: float) -> void:
	if is_on_ladder:
		var climb_dir := 0.0
		if Input.is_action_pressed("jump"):
			climb_dir -= 1.0
		if Input.is_action_pressed("crouch"):
			climb_dir += 1.0
		velocity.y = climb_dir * 150.0
	else:
		if not is_on_floor():
			velocity.y += gravity * delta

		if Input.is_action_just_pressed("jump") and is_on_floor():
			velocity.y = jump_velocity

	var direction := Input.get_axis("move_left", "move_right")
	if direction != 0.0:
		velocity.x = direction * speed
		if animated_sprite:
			animated_sprite.flip_h = direction < 0.0
	else:
		velocity.x = move_toward(velocity.x, 0.0, speed)

	var blend: float = absf(velocity.x) / speed
	if animation_tree:
		animated_sprite = animated_sprite
		animation_tree["parameters/move_blend/blend_position"] = blend

	move_and_slide()

